// Periodo: ultimi 30 giorni fino ad ora (Umami aggiunge da solo il confronto coi 30 precedenti).
// Una riga per ogni interrogazione: il nodo HTTP le esegue tutte con un solo nodo.
const a = $('Abbina').first().json;
const id = a.cliente.umami_id;
if (!id) throw new Error('cliente ' + a.slug + ' senza umami_id nel registro: ripubblica il sito dall\'editor');
const end = Date.now(); const start = end - 30 * 864e5; const prev = start - 30 * 864e5;
const base = 'https://stats.consulbuild.com/api/websites/' + id;
const q = 'startAt=' + start + '&endAt=' + end + '&timezone=Europe%2FRome';
const riga = (tipo, url) => ({ json: { tipo, url, start, end, prev } });
return [
  riga('stats', base + '/stats?' + q),
  riga('referrer', base + '/metrics?type=referrer&limit=20&' + q),
  riga('device', base + '/metrics?type=device&limit=10&' + q),
  riga('city', base + '/metrics?type=city&limit=10&' + q),
  riga('path', base + '/metrics?type=path&limit=20&' + q),
];

// Compone oggetto, HTML e testo del report. Solo numeri misurati: le sezioni senza dati si omettono.
const a = $('Abbina').first().json; const c = a.cliente;
const qs = $('Interrogazioni').all().map(i => i.json);
const ds = $('Umami dati').all().map(i => i.json.body);
const dato = t => { const k = qs.findIndex(q => q.tipo === t); return k >= 0 ? ds[k] : null; };
const st = dato('stats') || {}; const cmp = st.comparison || {};
const conta = nodo => $(nodo).all().map(i => i.json).filter(r => r && r.id).length;
const richieste = conta('Lead periodo'), richiestePrec = conta('Lead precedente');
const inizio = new Date(qs[0].start), fine = new Date(qs[0].end);
const LEAD_DAL = new Date('2026-09-06T00:00:00+02:00');
const fmt = d => d.toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Rome' });
const num = v => new Intl.NumberFormat('it-IT').format(v || 0);
const plur = (v, s, p) => num(v) + ' ' + (v === 1 ? s : p);
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const delta = (cur, prev) => {
  cur = cur || 0; prev = prev || 0;
  if (!prev) return { t: cur ? 'nei 30 giorni precedenti non c\'erano dati' : 'come nei 30 giorni precedenti', col: '#6b6b66' };
  const p = Math.round((cur - prev) / prev * 100);
  if (p > 0) return { t: '\u25B2 +' + p + '% sui 30 giorni precedenti', col: '#1f7a3a' };
  if (p < 0) return { t: '\u25BC ' + p + '% sui 30 giorni precedenti', col: '#b3261e' };
  return { t: '= come nei 30 giorni precedenti', col: '#6b6b66' };
};
const visite = st.visits || 0, visitatori = st.visitors || 0;
// Da dove arrivano (per visitatori con provenienza nota; il resto è diretto/link)
const cat = { 'Google': 0, 'Altri motori di ricerca': 0, 'Social (Facebook, Instagram\u2026)': 0, 'Altri siti': 0 };
for (const r of (dato('referrer') || [])) {
  const d = String(r.x || '').toLowerCase(); const y = r.y || 0; if (!d) continue;
  if (/google\./.test(d)) cat['Google'] += y;
  else if (/bing|duckduckgo|yahoo|ecosia|qwant/.test(d)) cat['Altri motori di ricerca'] += y;
  else if (/facebook|instagram|fb\.|linkedin|tiktok|whatsapp|t\.co|twitter|x\.com|youtube/.test(d)) cat['Social (Facebook, Instagram\u2026)'] += y;
  else cat['Altri siti'] += y;
}
const conRef = Object.values(cat).reduce((s, v) => s + v, 0);
const diretto = Math.max(visitatori - conRef, 0); const totRef = conRef + diretto;
const pct = v => Math.round(v / totRef * 100) + '%';
const provenienza = totRef ? [['Diretti o da un link (WhatsApp, biglietto, passaparola)', diretto], ...Object.entries(cat)].filter(([, v]) => v > 0).map(([k, v]) => [k, pct(v)]) : [];
// Smartphone o computer
let mob = 0, pc = 0;
for (const d of (dato('device') || [])) { if (/mobile|tablet/i.test(d.x)) mob += d.y || 0; else pc += d.y || 0; }
const totDev = mob + pc;
const dispositivi = totDev ? [['Smartphone e tablet', Math.round(mob / totDev * 100) + '%'], ['Computer', Math.round(pc / totDev * 100) + '%']] : [];
// Città
const citta = (dato('city') || []).filter(x => x.x).slice(0, 3).map(x => [x.x + (x.country && x.country !== 'IT' ? ' (' + x.country + ')' : ''), plur(x.y, 'visitatore', 'visitatori')]);
// Sezioni del sito guardate
const ET = { '/': 'Home', '/#servizi': 'Servizi', '/#lavori': 'Lavori realizzati', '/#processo': 'Come lavoriamo', '/#faq': 'Domande frequenti', '/#contatti': 'Modulo preventivo', '/#canali': 'Contatti' };
const sezioni = (dato('path') || []).filter(p => ET[p.x]).slice(0, 3).map(p => [ET[p.x], plur(p.y, 'visualizzazione', 'visualizzazioni')]);

const dVisite = delta(visite, cmp.visits), dVisitatori = delta(visitatori, cmp.visitors), dRich = delta(richieste, richiestePrec);
const notaLead = inizio < LEAD_DAL ? 'Il conteggio delle richieste dal modulo \u00e8 attivo dal 6 settembre 2026: quelle arrivate prima non compaiono qui.' : '';
const periodo = 'dal ' + fmt(inizio) + ' al ' + fmt(fine);
const subject = 'Il tuo sito nell\'ultimo mese: ' + plur(visite, 'visita', 'visite') + ' e ' + plur(richieste, 'richiesta di preventivo', 'richieste di preventivo');

// ---- HTML (tabelle e stili inline: funziona in Gmail, Outlook, Apple Mail) ----
const F = 'font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;';
const kpi = (n, l, d) => '<td width=\'33%\' valign=\'top\' style=\'padding:0 6px;\'><div style=\'' + F + 'font-size:34px;line-height:1.1;font-weight:700;color:#1c1c1a;\'>' + num(n) + '</div><div style=\'' + F + 'font-size:13px;color:#1c1c1a;margin-top:4px;\'>' + l + '</div><div style=\'' + F + 'font-size:12px;color:' + d.col + ';margin-top:4px;\'>' + esc(d.t) + '</div></td>';
const blocco = (titolo, righe) => !righe.length ? '' : '<tr><td style=\'padding:28px 0 0;\'><div style=\'' + F + 'font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#6b6b66;padding-bottom:8px;border-bottom:1px solid #e5e5e0;\'>' + titolo + '</div><table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'>' + righe.map(([k, v]) => '<tr><td style=\'' + F + 'font-size:15px;color:#1c1c1a;padding:10px 0;border-bottom:1px dotted #e5e5e0;\'>' + esc(k) + '</td><td align=\'right\' style=\'' + F + 'font-size:15px;color:#1c1c1a;padding:10px 0;border-bottom:1px dotted #e5e5e0;white-space:nowrap;\'>' + esc(v) + '</td></tr>').join('') + '</table></td></tr>';
const html = '<!DOCTYPE html><html lang=\'it\'><head><meta charset=\'utf-8\'><meta name=\'viewport\' content=\'width=device-width\'><title>' + esc(subject) + '</title></head>'
  + '<body style=\'margin:0;padding:0;background:#f4f4f2;\'>'
  + '<table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\' style=\'background:#f4f4f2;\'><tr><td align=\'center\' style=\'padding:32px 12px;\'>'
  + '<table width=\'560\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\' style=\'max-width:560px;width:100%;background:#ffffff;border:1px solid #e5e5e0;\'><tr><td style=\'padding:32px 32px 36px;\'>'
  + '<table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'>'
  + '<tr><td style=\'' + F + 'font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#1c1c1a;font-weight:700;padding-bottom:20px;border-bottom:2px solid #1c1c1a;\'>ConsulBuild</td></tr>'
  + '<tr><td style=\'padding-top:24px;\'><div style=\'' + F + 'font-size:24px;line-height:1.25;font-weight:700;color:#1c1c1a;\'>Il tuo sito nell\u2019ultimo mese</div><div style=\'' + F + 'font-size:13px;color:#6b6b66;margin-top:6px;\'>' + esc(c.dominio || '') + ' \u00b7 ' + esc(periodo) + '</div></td></tr>'
  + '<tr><td style=\'padding-top:20px;\'><div style=\'' + F + 'font-size:15px;line-height:1.5;color:#1c1c1a;\'>Buongiorno ' + esc(a.nomeSaluto) + ',<br>ecco cosa ha fatto il sito di ' + esc(c.azienda) + ' negli ultimi 30 giorni. Sono i dati reali raccolti dal sito, in forma anonima.</div></td></tr>'
  + '<tr><td style=\'padding-top:28px;\'><table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'><tr>' + kpi(visite, 'visite', dVisite) + kpi(visitatori, 'persone diverse', dVisitatori) + kpi(richieste, richieste === 1 ? 'richiesta di preventivo' : 'richieste di preventivo', dRich) + '</tr></table>' + (notaLead ? '<div style=\'' + F + 'font-size:12px;color:#6b6b66;margin-top:12px;\'>' + esc(notaLead) + '</div>' : '') + '</td></tr>'
  + blocco('Da dove arrivano', provenienza) + blocco('Smartphone o computer', dispositivi) + blocco('Da quali citt\u00e0', citta) + blocco('Cosa hanno guardato', sezioni)
  + '<tr><td style=\'padding-top:28px;\'><div style=\'' + F + 'font-size:12px;line-height:1.5;color:#6b6b66;\'>Le statistiche sono raccolte senza cookie e senza banner, nel rispetto della privacy dei visitatori: chi blocca gli script non viene contato, quindi i numeri sono prudenti. Una \u00abvisita\u00bb \u00e8 una sessione di navigazione; le richieste sono i moduli di preventivo compilati sul sito.</div></td></tr>'
  + '<tr><td style=\'padding-top:24px;border-top:1px solid #e5e5e0;margin-top:24px;\'><div style=\'' + F + 'font-size:14px;line-height:1.5;color:#1c1c1a;padding-top:20px;\'>Vuoi parlarne o hai un\u2019idea per il sito? Rispondi a questa e-mail: arriva direttamente a noi.<br><strong>ConsulBuild</strong> \u00b7 info@consulbuild.com</div></td></tr>'
  + '</table></td></tr></table></td></tr></table></body></html>';

const righeTxt = (t, r) => r.length ? '\n' + t.toUpperCase() + '\n' + r.map(([k, v]) => '- ' + k + ': ' + v).join('\n') + '\n' : '';
const text = 'CONSULBUILD \u2014 Il tuo sito nell\'ultimo mese\n' + (c.dominio || '') + ' \u00b7 ' + periodo + '\n\nBuongiorno ' + a.nomeSaluto + ',\necco cosa ha fatto il sito di ' + c.azienda + ' negli ultimi 30 giorni.\n\n'
  + plur(visite, 'visita', 'visite') + ' (' + dVisite.t + ')\n' + plur(visitatori, 'persona diversa', 'persone diverse') + ' (' + dVisitatori.t + ')\n' + plur(richieste, 'richiesta di preventivo', 'richieste di preventivo') + ' (' + dRich.t + ')\n' + (notaLead ? notaLead + '\n' : '')
  + righeTxt('Da dove arrivano', provenienza) + righeTxt('Smartphone o computer', dispositivi) + righeTxt('Da quali citt\u00e0', citta) + righeTxt('Cosa hanno guardato', sezioni)
  + '\nLe statistiche sono raccolte senza cookie e senza banner: chi blocca gli script non viene contato, quindi i numeri sono prudenti.\n\nVuoi parlarne? Rispondi a questa e-mail.\nConsulBuild \u00b7 info@consulbuild.com\n';

return [{ json: { slug: a.slug, azienda: c.azienda, to: a.to, subject, html, text, visite, visitatori, richieste, periodo_inizio: inizio.toISOString(), periodo_fine: fine.toISOString(), dryRun: !!a.dryRun, via: a.via } }];
